package com.hotel.dto;
import java.time.LocalDate;
public record AvailableRoomDto(long roomId,String roomNumber,Integer floor,String typeCode,String typeName,String bedType,int maxAdults,int maxChildren,String operationalStatus,String cleaningStatus,LocalDate checkIn,LocalDate checkOut){public long getRoomId(){return roomId;} public String getRoomNumber(){return roomNumber;} public Integer getFloor(){return floor;} public String getTypeCode(){return typeCode;} public String getTypeName(){return typeName;} public String getBedType(){return bedType;} public int getMaxAdults(){return maxAdults;} public int getMaxChildren(){return maxChildren;} public String getOperationalStatus(){return operationalStatus;} public String getCleaningStatus(){return cleaningStatus;} public LocalDate getCheckIn(){return checkIn;} public LocalDate getCheckOut(){return checkOut;}}
